import { Link, useLocation } from 'react-router-dom';
import { Menu, X } from 'lucide-react';
import { useState, useEffect } from 'react';

export default function Header() {
  const location = useLocation();
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [scrolled, setScrolled] = useState(false);

  useEffect(() => {
    const handleScroll = () => setScrolled(window.scrollY > 40);
    window.addEventListener('scroll', handleScroll, { passive: true });
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const navItems = [
    { href: '#about', label: 'About' },
    { href: '#contact', label: 'Contact' },
  ];

  const handleNavClick = (href: string) => {
    setIsMobileMenuOpen(false);
    if (href.startsWith('#')) {
      const el = document.querySelector(href);
      if (el) el.scrollIntoView({ behavior: 'smooth' });
    }
  };

  return (
    <header
      className={`fixed top-0 left-0 right-0 z-50 transition-all duration-300 ${
        scrolled
          ? 'bg-background/95 backdrop-blur-sm border-b border-border'
          : 'bg-transparent'
      }`}
    >
      <div className="max-w-6xl mx-auto px-6 md:px-12">
        <div className="flex h-16 md:h-20 items-center justify-between">
          {/* Wordmark */}
          <Link
            to="/"
            className="font-heading text-lg md:text-xl font-normal tracking-tight text-foreground hover:text-primary transition-colors duration-200"
          >
            Alex Morgan
          </Link>

          {/* Desktop nav */}
          <nav className="hidden md:flex items-center gap-8">
            {navItems.map((item) => (
              <button
                key={item.href}
                onClick={() => handleNavClick(item.href)}
                className="text-sm font-medium tracking-wide text-muted-foreground hover:text-primary transition-colors duration-200 cursor-pointer"
              >
                {item.label}
              </button>
            ))}
          </nav>

          {/* Mobile toggle */}
          <button
            onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
            className="md:hidden p-2 text-foreground hover:text-primary transition-colors"
            aria-label="Toggle menu"
          >
            {isMobileMenuOpen ? <X size={20} /> : <Menu size={20} />}
          </button>
        </div>

        {/* Mobile menu */}
        {isMobileMenuOpen && (
          <div className="md:hidden border-t border-border py-4 bg-background/95 backdrop-blur-sm">
            <nav className="flex flex-col gap-1">
              {navItems.map((item) => (
                <button
                  key={item.href}
                  onClick={() => handleNavClick(item.href)}
                  className="text-sm font-medium text-muted-foreground hover:text-primary py-3 text-left transition-colors duration-200 cursor-pointer"
                >
                  {item.label}
                </button>
              ))}
            </nav>
          </div>
        )}
      </div>
    </header>
  );
}

export default function Footer() {
  const currentYear = new Date().getFullYear();

  const scrollToTop = () => {
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  return (
    <footer className="border-t border-border bg-background">
      <div className="max-w-6xl mx-auto px-6 md:px-12 py-6">
        <div className="flex items-center justify-between">
          <p className="text-xs text-muted-foreground tracking-wide">
            © {currentYear} Alex Morgan
          </p>
          <button
            onClick={scrollToTop}
            className="text-xs text-muted-foreground hover:text-primary transition-colors duration-200 tracking-wide cursor-pointer"
          >
            Back to top ↑
          </button>
        </div>
      </div>
    </footer>
  );
}

import { Helmet } from '@dr.pogodin/react-helmet';
import { motion } from 'motion/react';
import { Github, Linkedin, Twitter, ArrowDown, Mail } from 'lucide-react';

// ─── Animation variants ───────────────────────────────────────────────────────

const fadeUp = {
  hidden: { opacity: 0, y: 32 },
  visible: (delay = 0) => ({
    opacity: 1,
    y: 0,
    transition: { duration: 0.5, delay, ease: 'easeOut' as const },
  }),
};

const fadeIn = {
  hidden: { opacity: 0, y: 20 },
  visible: {
    opacity: 1,
    y: 0,
    transition: { duration: 0.5, ease: 'easeOut' as const },
  },
};

// ─── Skills ───────────────────────────────────────────────────────────────────

const skills = [
  'UI/UX Design',
  'React',
  'TypeScript',
  'Node.js',
  'Figma',
  'Motion Design',
  'Design Systems',
  'Accessibility',
];

// ─── Social links ─────────────────────────────────────────────────────────────

const socials = [
  { label: 'GitHub', href: 'https://github.com', icon: Github },
  { label: 'LinkedIn', href: 'https://linkedin.com', icon: Linkedin },
  { label: 'Twitter / X', href: 'https://twitter.com', icon: Twitter },
];

// ─── Component ────────────────────────────────────────────────────────────────

export default function HomePage() {
  const scrollToSection = (id: string) => {
    const el = document.getElementById(id);
    if (el) el.scrollIntoView({ behavior: 'smooth' });
  };

  return (
    <>
      <Helmet>
        <title>Alex Morgan — Designer & Developer</title>
        <meta
          name="description"
          content="Alex Morgan is a designer and developer crafting thoughtful digital experiences."
        />
      </Helmet>

      {/* ── HERO ─────────────────────────────────────────────────────────── */}
      <section className="relative min-h-screen flex flex-col justify-center px-6 md:px-12 max-w-6xl mx-auto">
        {/* Accent rule */}
        <motion.div
          initial={{ scaleX: 0, opacity: 0 }}
          animate={{ scaleX: 1, opacity: 1 }}
          transition={{ duration: 0.6, ease: 'easeOut' as const, delay: 0.1 }}
          style={{ originX: 0 }}
          className="w-12 h-px bg-primary mb-8"
        />

        {/* Name — oversized, breaking the grid */}
        <motion.h1
          variants={fadeUp}
          initial="hidden"
          animate="visible"
          custom={0.15}
          className="font-heading text-[clamp(3.5rem,12vw,10rem)] leading-[0.9] tracking-tight text-foreground mb-6"
        >
          Alex
          <br />
          Morgan
        </motion.h1>

        {/* Tagline */}
        <motion.p
          variants={fadeUp}
          initial="hidden"
          animate="visible"
          custom={0.3}
          className="text-base md:text-lg text-muted-foreground max-w-md leading-relaxed mb-10"
        >
          Designer & developer crafting thoughtful digital experiences — where
          clarity meets craft.
        </motion.p>

        {/* CTA link */}
        <motion.button
          variants={fadeUp}
          initial="hidden"
          animate="visible"
          custom={0.45}
          onClick={() => scrollToSection('about')}
          className="inline-flex items-center gap-2 text-sm font-medium text-primary border-b border-primary pb-0.5 hover:gap-3 transition-all duration-200 w-fit cursor-pointer"
        >
          View my work
        </motion.button>

        {/* Scroll indicator */}
        <motion.button
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ delay: 1, duration: 0.6 }}
          onClick={() => scrollToSection('about')}
          className="absolute bottom-10 left-6 md:left-12 flex flex-col items-center gap-2 text-muted-foreground hover:text-primary transition-colors duration-200 cursor-pointer"
          aria-label="Scroll down"
        >
          <span className="text-xs tracking-widest uppercase rotate-0">Scroll</span>
          <motion.div
            animate={{ y: [0, 6, 0] }}
            transition={{ repeat: Infinity, duration: 1.8, ease: 'easeInOut' as const }}
          >
            <ArrowDown size={14} />
          </motion.div>
        </motion.button>
      </section>

      {/* Section divider */}
      <div className="max-w-6xl mx-auto px-6 md:px-12">
        <div className="border-t border-border" />
      </div>

      {/* ── ABOUT ────────────────────────────────────────────────────────── */}
      <section id="about" className="py-24 md:py-36 px-6 md:px-12 max-w-6xl mx-auto">
        <div className="grid grid-cols-1 md:grid-cols-[200px_1fr] gap-12 md:gap-20">
          {/* Left: label */}
          <motion.div
            variants={fadeIn}
            initial="hidden"
            whileInView="visible"
            viewport={{ once: true }}
            className="md:pt-1"
          >
            <span className="text-xs font-medium tracking-[0.2em] uppercase text-primary">
              About Me
            </span>
          </motion.div>

          {/* Right: content */}
          <motion.div
            variants={fadeIn}
            initial="hidden"
            whileInView="visible"
            viewport={{ once: true }}
          >
            <div className="grid grid-cols-1 lg:grid-cols-[1fr_220px] gap-10 mb-12">
              {/* Text */}
              <div className="flex flex-col gap-5">
                <p className="text-foreground/90 leading-relaxed text-base md:text-lg">
                  I'm a multidisciplinary designer and developer with over eight years of
                  experience building products that people actually enjoy using. My work
                  sits at the intersection of visual craft and technical precision.
                </p>
                <p className="text-muted-foreground leading-relaxed">
                  Previously at Figma, Stripe, and a handful of early-stage startups, I've
                  led design systems, shipped consumer apps, and helped teams move from
                  zero to one. I care deeply about accessibility, performance, and the
                  small details that make an interface feel alive.
                </p>
                <p className="text-muted-foreground leading-relaxed">
                  When I'm not pushing pixels or writing TypeScript, you'll find me hiking
                  the Pacific Crest Trail, experimenting with film photography, or reading
                  about the history of graphic design.
                </p>
              </div>

              {/* Portrait */}
              <div className="hidden lg:block">
                <div className="relative w-full aspect-[3/4] overflow-hidden rounded-sm">
                  <img
                    src="/airo-assets/images/pages/about/portrait"
                    alt="Alex Morgan"
                    className="w-full h-full object-cover object-top grayscale"
                    width={220}
                    height={293}
                  />
                  {/* Amber overlay tint */}
                  <div className="absolute inset-0 bg-primary/10 mix-blend-multiply" />
                </div>
              </div>
            </div>

            {/* Skills */}
            <div className="flex flex-wrap gap-2">
              {skills.map((skill) => (
                <span
                  key={skill}
                  className="text-xs font-medium tracking-wide px-3 py-1.5 border border-border text-muted-foreground hover:border-primary hover:text-primary transition-colors duration-200 rounded-sm"
                >
                  {skill}
                </span>
              ))}
            </div>
          </motion.div>
        </div>
      </section>

      {/* Section divider */}
      <div className="max-w-6xl mx-auto px-6 md:px-12">
        <div className="border-t border-border" />
      </div>

      {/* ── CONTACT ──────────────────────────────────────────────────────── */}
      <section id="contact" className="py-24 md:py-36 px-6 md:px-12 max-w-6xl mx-auto">
        <motion.div
          variants={fadeIn}
          initial="hidden"
          whileInView="visible"
          viewport={{ once: true }}
          className="max-w-2xl"
        >
          {/* Overline */}
          <span className="text-xs font-medium tracking-[0.2em] uppercase text-primary block mb-6">
            Get in touch
          </span>

          {/* Heading */}
          <h2 className="font-heading text-[clamp(2.5rem,6vw,5rem)] leading-[1] tracking-tight text-foreground mb-8">
            Let's work
            <br />
            together.
          </h2>

          {/* Email link */}
          <a
            href="mailto:hello@alexmorgan.design"
            className="group inline-flex items-center gap-3 text-base md:text-lg text-foreground border-b border-muted-foreground pb-0.5 hover:border-primary hover:text-primary transition-colors duration-200 mb-12"
          >
            <Mail size={18} className="text-muted-foreground group-hover:text-primary transition-colors duration-200" />
            hello@alexmorgan.design
          </a>

          {/* Social icons */}
          <div className="flex items-center gap-5">
            {socials.map(({ label, href, icon: Icon }) => (
              <a
                key={label}
                href={href}
                target="_blank"
                rel="noopener noreferrer"
                aria-label={label}
                className="text-muted-foreground hover:text-primary transition-colors duration-200"
              >
                <Icon size={20} strokeWidth={1.5} />
              </a>
            ))}
          </div>
        </motion.div>
      </section>
    </>
  );
}
